import mongoose, { Schema } from "mongoose";

const PurchaseSchema = new Schema(
  {
    userId: { type: Schema.Types.ObjectId, ref: "User", required: true },
    itemId: { type: Schema.Types.ObjectId, ref: "Item", required: true },
    quantity: { type: Number, required: true }, // Number of big packets purchased
    totalCost: { type: Number, required: true }, // Total cost for all big packets
    perItemCost: { type: Number, required: true }, // Cost per big packet
    smallPacketsPerBox: { type: Number, required: true }, // Snapshot of small packets per box at purchase time
    sellingPricePerSmallPacket: { type: Number, default: 0 }, // Snapshot of selling price per small packet at purchase time
    sellingPricePerBox: { type: Number, default: 0 }, // Calculated selling price per big packet
    profitPerBox: { type: Number, default: 0 }, // Calculated profit per big packet
    profitMarginPercent: { type: Number, default: 0 }, // Profit margin percentage
    date: { type: Date, default: Date.now },
    notes: { type: String }
  },
  { timestamps: true }
);

export default mongoose.models.Purchase || mongoose.model("Purchase", PurchaseSchema);
